CREATE TABLE utilisateurs(id BIGSERIAL PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL,actif BOOLEAN NOT NULL);
CREATE TABLE annees_scolaires(id BIGSERIAL PRIMARY KEY,libelle VARCHAR(9) NOT NULL UNIQUE,active BOOLEAN NOT NULL);
CREATE TABLE filieres(id BIGSERIAL PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,nom VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE classes(id BIGSERIAL PRIMARY KEY,nom VARCHAR(50) NOT NULL,niveau VARCHAR(30) NOT NULL);
CREATE TABLE parents(id BIGSERIAL PRIMARY KEY,prenom VARCHAR(50) NOT NULL,nom VARCHAR(50) NOT NULL,telephone VARCHAR(30),email VARCHAR(120));
CREATE TABLE eleves(id BIGSERIAL PRIMARY KEY,prenom VARCHAR(50) NOT NULL,nom VARCHAR(50) NOT NULL,matricule VARCHAR(30) UNIQUE,sexe VARCHAR(20),telephone VARCHAR(30),parent_id BIGINT NOT NULL REFERENCES parents(id));
CREATE TABLE enseignants(id BIGSERIAL PRIMARY KEY,prenom VARCHAR(50) NOT NULL,nom VARCHAR(50) NOT NULL,telephone VARCHAR(30));
CREATE TABLE personnels_administratifs(id BIGSERIAL PRIMARY KEY,prenom VARCHAR(50) NOT NULL,nom VARCHAR(50) NOT NULL,role VARCHAR(30) NOT NULL);
CREATE TABLE matieres(id BIGSERIAL PRIMARY KEY,nom VARCHAR(80) NOT NULL,code VARCHAR(30) NOT NULL UNIQUE,coefficient NUMERIC(6,2) NOT NULL,niveau VARCHAR(20) NOT NULL,filiere_id BIGINT NOT NULL REFERENCES filieres(id));
CREATE TABLE cours(id BIGSERIAL PRIMARY KEY,classe_id BIGINT NOT NULL REFERENCES classes(id),matiere_id BIGINT NOT NULL REFERENCES matieres(id),enseignant_id BIGINT NOT NULL REFERENCES enseignants(id));
CREATE TABLE emplois_du_temps(id BIGSERIAL PRIMARY KEY,classe_id BIGINT NOT NULL REFERENCES classes(id),cours_id BIGINT NOT NULL REFERENCES cours(id),jour VARCHAR(15) NOT NULL,heure_debut VARCHAR(10) NOT NULL,heure_fin VARCHAR(10) NOT NULL);
CREATE TABLE evaluations(id BIGSERIAL PRIMARY KEY,libelle VARCHAR(80) NOT NULL,matiere_id BIGINT NOT NULL REFERENCES matieres(id),classe_id BIGINT NOT NULL REFERENCES classes(id),annee_scolaire_id BIGINT NOT NULL REFERENCES annees_scolaires(id));
CREATE TABLE notes(id BIGSERIAL PRIMARY KEY,valeur NUMERIC(5,2) NOT NULL,eleve_id BIGINT NOT NULL REFERENCES eleves(id),evaluation_id BIGINT NOT NULL REFERENCES evaluations(id));
CREATE TABLE bulletins(id BIGSERIAL PRIMARY KEY,eleve_id BIGINT NOT NULL REFERENCES eleves(id),classe_id BIGINT NOT NULL REFERENCES classes(id),annee_scolaire_id BIGINT NOT NULL REFERENCES annees_scolaires(id),moyenne NUMERIC(5,2) NOT NULL,annuel BOOLEAN NOT NULL);
CREATE TABLE absences(id BIGSERIAL PRIMARY KEY,eleve_id BIGINT NOT NULL REFERENCES eleves(id),date DATE NOT NULL,justifiee BOOLEAN NOT NULL,motif VARCHAR(255));
CREATE TABLE inscriptions(id BIGSERIAL PRIMARY KEY,eleve_id BIGINT NOT NULL REFERENCES eleves(id),classe_id BIGINT NOT NULL REFERENCES classes(id),annee_scolaire_id BIGINT NOT NULL REFERENCES annees_scolaires(id),redoublant BOOLEAN NOT NULL,UNIQUE(eleve_id,annee_scolaire_id));
CREATE TABLE paiements(id BIGSERIAL PRIMARY KEY,eleve_id BIGINT NOT NULL REFERENCES eleves(id),annee_scolaire_id BIGINT NOT NULL REFERENCES annees_scolaires(id),montant NUMERIC(12,2) NOT NULL,date_paiement DATE NOT NULL,reference VARCHAR(80) NOT NULL);
CREATE TABLE refresh_tokens(id BIGSERIAL PRIMARY KEY,token_hash VARCHAR(128) NOT NULL UNIQUE,utilisateur_id BIGINT NOT NULL REFERENCES utilisateurs(id),expires_at TIMESTAMPTZ NOT NULL,revoked BOOLEAN NOT NULL);
CREATE TABLE audit_logs(id BIGSERIAL PRIMARY KEY,date_heure TIMESTAMPTZ NOT NULL,action VARCHAR(100) NOT NULL,username VARCHAR(100),cible VARCHAR(100),details TEXT);